// Guide pp.259, 326: optimal policing adds 20 aura; excessive presence can cost 10.
// The continuous decline from 100 to 200 percent is reconstruction tuning.
export function policeAura(t){const presence=Math.max(0,t.policePresence??t.policeCoverage??0);return presence<=100?presence*.2:Math.max(-10,20-(presence-100)*.3);}
// Manual p.113 names traffic as a local aura pressure. Radius and strength are tuned values.
export function localTrafficPenalty(c,home){let pressure=0;for(let y=Math.max(0,home.y-2);y<=Math.min(c.size-1,home.y+2);y++)for(let x=Math.max(0,home.x-2);x<=Math.min(c.size-1,home.x+2);x++){const t=c.tiles[y*c.size+x],distance=Math.max(Math.abs(home.x-x),Math.abs(home.y-y));const load=Math.max(t.type==='road'?(t.traffic||0)/40:0,t.highway?(t.highwayTraffic||0)/160:0);pressure=Math.max(pressure,load/(1+distance));}return Math.min(8,pressure*4);}
export function auraBreakdown(c,t){if(t.type!=='residential'||!t.level)return null;const factors={baseline:50,medicalResearch:t.medicalResearchAura||0,police:policeAura(t),education:(c.civic.education-40)*.3,health:(c.civic.lifeExpectancy-59)*.6,crime:-t.crime*.35,air:-t.airPollution*.25,property:(t.landValue-50)*.3,taxes:-(c.finance.taxes.residential-7)*3,parking:c.civic.ordinances.parkingFines?-3:0,traffic:-localTrafficPenalty(c,t)};const raw=Object.values(factors).reduce((sum,n)=>sum+n,0),value=Math.max(0,Math.min(100,raw));return{factors,raw,value,capAdjustment:value-raw};}
const labels={baseline:'Baseline',medicalResearch:'Medical research nearby',police:'Local police presence',education:'City education',health:'Life expectancy',crime:'Local crime',air:'Local air pollution',property:'Local property value',taxes:'Residential tax rate',parking:'Parking fines',traffic:'Nearby road and highway traffic'};
export function auraReport(c,t){const b=auraBreakdown(c,t);if(!b)return '';const fmt=n=>(n>0?'+':'')+(Math.abs(n)<.05?0:n).toFixed(1);return `<details><summary>Why residents feel this way · ${b.value.toFixed(1)} / 100 aura</summary><p>Current happiness at this occupied residential tile. Each factor adds or subtracts points.</p><div class="table-scroll"><table><thead><tr><th>Factor</th><th>Aura points</th></tr></thead><tbody>${Object.entries(b.factors).map(([key,value])=>`<tr><td>${labels[key]}</td><td>${fmt(value)}</td></tr>`).join('')}${b.capAdjustment?`<tr><td>Adjustment to the 0–100 range</td><td>${fmt(b.capAdjustment)}</td></tr>`:''}<tr><th>Current aura</th><td>${b.value.toFixed(1)}</td></tr></tbody></table></div><p>Police presence: ${(t.policePresence??t.policeCoverage??0).toFixed(1)}%. ${((t.policePresence??t.policeCoverage??0)>100)?'Overlapping precincts exceed optimal coverage here. Excess policing reduces the wellbeing benefit; consider spacing stations farther apart.':'Police coverage improves wellbeing up to its optimum.'}</p><p>Traffic pressure uses the busiest road or highway within two tiles, reduced by distance. Transit, carpooling and alternate routes can reduce it. Pollution is a separate effect. These weights are reconstruction tuning.</p></details>`;}
